document.addEventListener('DOMContentLoaded', function() {
    const cart = {};
    const cartList = document.getElementById('q9-cart');

    // Get all add buttons
    const addButtons = document.querySelectorAll('.q9-add');

    // Add event listeners to all buttons
    addButtons.forEach(button => {
        button.addEventListener('click', function() {
            const name = this.getAttribute('data-name');
            const price = parseInt(this.getAttribute('data-price'));

            // Add item to cart or increment count
            if (cart[name]) {
                cart[name].count++;
            } else {
                cart[name] = { price, count: 1 };
            }

            // Update cart display
            updateCartDisplay();
            updateItemCount();
        });
    });

    function updateCartDisplay() {
        // Clear current cart
        cartList.innerHTML = '';

        // Add each item to cart
        for (const name in cart) {
            const item = cart[name];
            const li = document.createElement('li');
            li.innerHTML = `${name} x${item.count} <button class="q9-dec">-</button> <button class="q9-inc">+</button>`;
            cartList.appendChild(li);
        }
    }

    function updateItemCount() {
        const count = Object.values(cart).reduce((total, item) => total + item.count, 0);
        const countElement = document.getElementById('q9-count');
        if (countElement) {
            countElement.textContent = count + (count === 1 ? ' item' : ' items');
        }
    }

    // Handle increment and decrement buttons using event delegation
    cartList.addEventListener('click', function(e) {
        if (e.target.classList.contains('q9-dec') || e.target.classList.contains('q9-inc')) {
            const li = e.target.parentElement;
            const text = li.textContent;
            const name = text.split(' x')[0];

            if (cart[name]) {
                if (e.target.classList.contains('q9-dec')) {
                    cart[name].count--;
                    if (cart[name].count <= 0) {
                        delete cart[name];
                    }
                } else {
                    cart[name].count++;
                }

                // Update cart display
                updateCartDisplay();
                updateItemCount();
            }
        }
    });

    // Initialize count on page load
    updateItemCount();
});
```

